@parity "dart2wasm/lib/modules.dart:31 ModuleMetadataBuilder.buildModuleMetadata" function build_module_metadata(self::ModuleMetadataBuilder; emit_as_main::Bool = false, skip_emit::Bool = false)::ModuleMetadata
    local id = self._counter
    self._counter += 1
    local module_import_name = Util.module_name_from_id(id)
    return ModuleMetadata__(module_import_name,
                            WasmCompilerOptions_module_name_for_id(self.options.output_file, id; emit_as_main = emit_as_main);
                            skip_emit = skip_emit, is_main = id == WasmCompilerOptions_main_module_id())
end

